<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Booking extends Model { public const BLOCKING=['pending','approved']; protected $fillable=['booking_code','user_id','meeting_room_id','title','description','start_at','end_at','participant_count','status','rejection_reason','approved_by','approved_at','cancelled_at']; protected function casts(): array{return ['start_at'=>'datetime','end_at'=>'datetime','approved_at'=>'datetime','cancelled_at'=>'datetime'];} public function user():BelongsTo{return $this->belongsTo(User::class);} public function room():BelongsTo{return $this->belongsTo(MeetingRoom::class,'meeting_room_id');} public function approver():BelongsTo{return $this->belongsTo(User::class,'approved_by');} public function histories():HasMany{return $this->hasMany(BookingStatusHistory::class);} }
